#### 2.2.3 editTable_resetColumnRender 重新设置列的渲染，返回null 或者不设置返回值使用平台渲染，不支持异步
```javascript
this.editTable_resetColumnRender = ({ _this, _rootThis, text, record, field }) => {
  if (field === 'HR_KQGL_PARTICIPATEIN_REVISEDETAIL_s_out2' && text==='缺岗') {
      return `<span style="color: red">${text}</span>`
  }
}
```

#### 2.3.4 editTable_resetColumnPermission 重新设置列的权限，不支持异步
```javascript
this.editTable_resetColumnPermission = ({ _this, _rootThis, text, record, field }) => {
    return { disabled: true, readOnly: true, must: true }  
}
```
#### 2.3.5 editTable_resetColumnInfoItem 重新设置列的组件属性，不支持异步
```javascript
this_editTable_resetColumnInfoItem = ({_this, _rootThis, text, record, field, infoItem}) => {
    //例子：组件改为Markdown
    return {type: 'Markdown'}
}
```

#### 2.3.6 editTable_resetColumnRequiredValidator 重新设置列必填项校验，常用于子表 markdown，不支持异步
```javascript
this_editTable_resetColumnRequiredValidator = ({_this, _rootThis, text, record, field, infoItem}) => {
return {message: '不能为空'}
}
```
#### 2.3.7 editTable_resetColumns 重新设置表头
```javascript
this_editTable_resetColumns = ({_rootThis, _this, columns}) => { return columns; }
```

