this.userSelect_customDepartTreeList = ({ _this, _rootThis, data }) => {
    //data 平台默认返回的部门树数据
    // 递归移除树形结构中指定名称的节点
    function removeNodeByName(treeData, name) {
      // 对数组进行过滤，创建新数组避免直接修改原数据
      return treeData.filter(node => {
        // 如果当前节点是要删除的节点，返回false将其过滤掉
        if (node.title === name) {
          return false;
        }
        // 如果当前节点有子节点，递归处理子节点
        if (node.children && node.children.length > 0) {
          // 递归处理子节点，并更新当前节点的children
          node.children = removeNodeByName(node.children, name);
        }
        // 保留当前节点
        return true;
      });
    }   
    return removeNodeByName(data, '部门1')
}
