当页面首次加载且用户未主动设置查询条件时，可以在回调中动态设置默认的时间范围（例如：当天的开始时间到当前时间），并同步更新组件状态。

```javascript
this.give.getDataCallback = (result) => {
  // 判断搜索时间条件是否为空（首次加载时通常为空）
  if (this.state.search_tm_s == null && this.state.search_tm_e == null) {
    const now = _tool.dayjs();
    // 设置当天的开始时间 (00:00:00)
    const startTime = now.startOf('day').format('YYYY-MM-DD HH:mm:ss');
    // 设置当前时间 (精确到分)
    const endTime = now.format('YYYY-MM-DD HH:mm:00');

    // 将默认时间同步更新到组件状态中
    this.setState({ 
      search_tm_s: startTime, 
      search_tm_e: endTime 
    });
  }
  return true
}
